-- Accounts, sessions, MFA, one-time tokens, audit log, throttles, idempotency.
-- Source of truth: docs/contracts/data-model.md and docs/contracts/auth.md.
-- Conventions (db/CLAUDE.md): UUIDv7 ids generated by the DAL (no DEFAULT),
-- timestamptz in UTC, values that rules depend on come from the app clock
-- (DEFAULT now() is only a fallback), invariants as named constraints.

-- migrate:up

-- citext is a trusted extension: migrator installs it with CREATE on the
-- database (granted by roles.sql).
CREATE EXTENSION IF NOT EXISTS citext WITH SCHEMA public;

-- Text rule shared by every user-text column (data-model.md "Text"): length in
-- code points, trimmed, Unicode NFC, no C0/C1 control characters.
-- Explicit code-point ranges keep this independent of the server locale.
CREATE FUNCTION is_clean_text(t text, min_len integer, max_len integer)
RETURNS boolean
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
RETURN char_length(t) BETWEEN min_len AND max_len
   AND t IS NFC NORMALIZED
   AND t !~ '^[ \t\n\r  -​　﻿]'
   AND t !~ '[ \t\n\r  -​　﻿]$'
   AND t !~ '[\u0001-\u001f\u007f-\u009f]';

-- Emails: citext, stored lowercased, at most 254 characters, one "@".
CREATE FUNCTION is_valid_email(e citext)
RETURNS boolean
LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
RETURN char_length(e::text) BETWEEN 3 AND 254
   AND e::text = lower(e::text)
   AND e::text ~ '^[^@[:space:]]+@[^@[:space:]]+$';

CREATE TYPE user_status AS ENUM ('active', 'pending_deletion');
CREATE TYPE session_status AS ENUM ('mfa_pending', 'active');
CREATE TYPE device_browser AS ENUM ('safari', 'chrome', 'firefox', 'edge', 'samsung_internet', 'other', 'unknown');
CREATE TYPE device_os AS ENUM ('ios', 'ipados', 'android', 'macos', 'windows', 'linux', 'chromeos', 'other', 'unknown');
CREATE TYPE user_token_purpose AS ENUM ('password_reset', 'email_change', 'email_change_cancel');
CREATE TYPE webauthn_challenge_purpose AS ENUM ('register', 'mfa', 'reauth', 'password_reset');
CREATE TYPE idempotency_resource_type AS ENUM ('budget', 'transaction');
CREATE TYPE security_event_type AS ENUM (
  -- sign-up and sign-in
  'signup', 'login_succeeded', 'login_failed', 'mfa_succeeded', 'mfa_failed', 'mfa_locked',
  'recovery_code_used', 'reauth_succeeded', 'reauth_failed', 'logout',
  -- sessions
  'session_revoked', 'sessions_revoked_others',
  -- password and email
  'password_changed', 'password_reset_requested', 'password_reset_completed',
  'email_change_requested', 'email_changed', 'email_change_cancelled',
  -- MFA
  'mfa_enabled', 'mfa_factor_added', 'mfa_factor_removed', 'mfa_disabled',
  'recovery_codes_regenerated', 'recovery_codes_retired', 'passkey_counter_regression',
  -- data rights
  'data_exported', 'account_deletion_requested', 'account_deletion_cancelled',
  -- budgets
  'budget_invitation_created', 'budget_invitation_accepted', 'budget_invitation_revoked',
  'budget_member_removed', 'budget_ownership_transferred', 'budget_deleted', 'budget_restored',
  -- admin
  'admin_signup_invite_created', 'admin_mfa_reset', 'admin_sessions_revoked'
);

-- ---------------------------------------------------------------- users
CREATE TABLE users (
  id                    uuid        PRIMARY KEY,
  email                 citext      NOT NULL,                     -- PII
  display_name          text        NOT NULL,                     -- PII
  password_hash         text        NOT NULL,                     -- Secret
  email_verified_at     timestamptz NOT NULL,
  status                user_status NOT NULL DEFAULT 'active',
  deletion_requested_at timestamptz,
  purge_after           timestamptz,
  created_at            timestamptz NOT NULL DEFAULT now(),
  updated_at            timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT users_email_key UNIQUE (email),
  CONSTRAINT users_email_check CHECK (is_valid_email(email)),
  CONSTRAINT users_display_name_check CHECK (is_clean_text(display_name, 1, 50)),
  -- argon2id PHC strings only: plaintext or other schemes can never be stored.
  CONSTRAINT users_password_hash_check CHECK (password_hash LIKE '$argon2id$%' AND char_length(password_hash) <= 512),
  CONSTRAINT users_deletion_state_check CHECK (
    (status = 'pending_deletion') = (deletion_requested_at IS NOT NULL AND purge_after IS NOT NULL)
  ),
  -- Stricter than the contract's pair: an active user carries no deletion timestamps.
  CONSTRAINT users_deletion_fields_check CHECK (
    status = 'pending_deletion' OR (deletion_requested_at IS NULL AND purge_after IS NULL)
  ),
  CONSTRAINT users_purge_after_check CHECK (
    purge_after IS NULL OR purge_after = deletion_requested_at + interval '30 days'
  )
);
CREATE INDEX users_purge_after_idx ON users (purge_after) WHERE status = 'pending_deletion';

-- ---------------------------------------------------------------- sessions
CREATE TABLE sessions (
  id                  uuid           PRIMARY KEY,
  user_id             uuid           NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  token_hash          bytea          NOT NULL,                    -- Secret: SHA-256 of the cookie token
  csrf_token          text           NOT NULL,                    -- Secret
  status              session_status NOT NULL,
  created_at          timestamptz    NOT NULL,
  updated_at          timestamptz    NOT NULL,
  last_seen_at        timestamptz    NOT NULL,
  expires_at          timestamptz    NOT NULL,
  absolute_expires_at timestamptz    NOT NULL,
  mfa_verified_at     timestamptz,
  reauth_at           timestamptz,
  mfa_failed_attempts smallint       NOT NULL DEFAULT 0,
  device_browser      device_browser NOT NULL,                    -- PII (low)
  device_os           device_os      NOT NULL,                    -- PII (low)
  CONSTRAINT sessions_token_hash_key UNIQUE (token_hash),
  CONSTRAINT sessions_token_hash_check CHECK (octet_length(token_hash) = 32),
  CONSTRAINT sessions_csrf_token_check CHECK (csrf_token ~ '^[A-Za-z0-9_-]{43,64}$'),
  CONSTRAINT sessions_expires_after_created_check CHECK (expires_at > created_at),
  CONSTRAINT sessions_absolute_expiry_check CHECK (absolute_expires_at = created_at + interval '90 days'),
  CONSTRAINT sessions_expires_within_absolute_check CHECK (expires_at <= absolute_expires_at),
  CONSTRAINT sessions_pending_check CHECK (
    status = 'active' OR (reauth_at IS NULL AND expires_at <= created_at + interval '10 minutes')
  ),
  CONSTRAINT sessions_mfa_failed_attempts_check CHECK (mfa_failed_attempts BETWEEN 0 AND 5)
);
CREATE INDEX sessions_user_id_idx ON sessions (user_id);
CREATE INDEX sessions_expires_at_idx ON sessions (expires_at);

-- ---------------------------------------------------------------- sign-up invites
CREATE TABLE signup_invites (
  id              uuid        PRIMARY KEY,
  email           citext      NOT NULL,                           -- PII
  token_hash      bytea       NOT NULL,                           -- Secret
  created_at      timestamptz NOT NULL,
  updated_at      timestamptz NOT NULL,
  expires_at      timestamptz NOT NULL,
  used_at         timestamptz,
  revoked_at      timestamptz,
  used_by_user_id uuid        REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT signup_invites_token_hash_key UNIQUE (token_hash),
  CONSTRAINT signup_invites_token_hash_check CHECK (octet_length(token_hash) = 32),
  CONSTRAINT signup_invites_email_check CHECK (is_valid_email(email)),
  CONSTRAINT signup_invites_expiry_check CHECK (expires_at = created_at + interval '7 days'),
  CONSTRAINT signup_invites_used_or_revoked_check CHECK (NOT (used_at IS NOT NULL AND revoked_at IS NOT NULL)),
  CONSTRAINT signup_invites_used_by_check CHECK (used_by_user_id IS NULL OR used_at IS NOT NULL)
);
CREATE UNIQUE INDEX signup_invites_open_email_key ON signup_invites (email)
  WHERE used_at IS NULL AND revoked_at IS NULL;
CREATE INDEX signup_invites_expires_at_idx ON signup_invites (expires_at);

-- ---------------------------------------------------------------- one-time email tokens
CREATE TABLE user_tokens (
  id                      uuid               PRIMARY KEY,
  user_id                 uuid               NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  purpose                 user_token_purpose NOT NULL,
  token_hash              bytea              NOT NULL,            -- Secret
  email                   citext,                                 -- PII
  requested_by_session_id uuid               REFERENCES sessions (id) ON DELETE CASCADE,
  mfa_failed_attempts     smallint           NOT NULL DEFAULT 0,
  created_at              timestamptz        NOT NULL,
  updated_at              timestamptz        NOT NULL,
  expires_at              timestamptz        NOT NULL,
  used_at                 timestamptz,
  CONSTRAINT user_tokens_token_hash_key UNIQUE (token_hash),
  CONSTRAINT user_tokens_token_hash_check CHECK (octet_length(token_hash) = 32),
  CONSTRAINT user_tokens_email_check CHECK ((purpose = 'password_reset') = (email IS NULL)),
  CONSTRAINT user_tokens_email_format_check CHECK (email IS NULL OR is_valid_email(email)),
  CONSTRAINT user_tokens_session_check CHECK ((purpose = 'email_change') = (requested_by_session_id IS NOT NULL)),
  CONSTRAINT user_tokens_mfa_failed_attempts_check CHECK (mfa_failed_attempts BETWEEN 0 AND 5),
  -- reset: 30 minutes; email change and cancel: 24 hours (auth.md §8, §9).
  CONSTRAINT user_tokens_expiry_check CHECK (
    (purpose = 'password_reset' AND expires_at = created_at + interval '30 minutes')
    OR (purpose <> 'password_reset' AND expires_at = created_at + interval '24 hours')
  )
);
CREATE UNIQUE INDEX user_tokens_open_purpose_key ON user_tokens (user_id, purpose)
  WHERE used_at IS NULL AND purpose <> 'email_change_cancel';
CREATE INDEX user_tokens_user_purpose_created_idx ON user_tokens (user_id, purpose, created_at);
CREATE INDEX user_tokens_requested_by_session_idx ON user_tokens (requested_by_session_id)
  WHERE requested_by_session_id IS NOT NULL;
CREATE INDEX user_tokens_expires_at_idx ON user_tokens (expires_at);

-- ---------------------------------------------------------------- TOTP
CREATE TABLE totp_credentials (
  user_id           uuid        PRIMARY KEY REFERENCES users (id) ON DELETE CASCADE,
  key_id            text        NOT NULL,
  secret_ciphertext bytea       NOT NULL,                         -- Secret: nonce || ciphertext || tag
  confirmed_at      timestamptz,
  last_used_step    bigint,
  created_at        timestamptz NOT NULL,
  updated_at        timestamptz NOT NULL,
  CONSTRAINT totp_credentials_key_id_check CHECK (key_id ~ '^k[0-9]{1,4}$'),
  -- 12-byte nonce + at least 1 byte + 16-byte tag
  CONSTRAINT totp_credentials_ciphertext_check CHECK (octet_length(secret_ciphertext) BETWEEN 29 AND 256),
  CONSTRAINT totp_credentials_last_used_step_check CHECK (last_used_step IS NULL OR last_used_step >= 0)
);
CREATE INDEX totp_credentials_key_id_idx ON totp_credentials (key_id);

-- ---------------------------------------------------------------- passkeys
CREATE TABLE webauthn_credentials (
  id            uuid        PRIMARY KEY,
  user_id       uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  credential_id bytea       NOT NULL,
  public_key    bytea       NOT NULL,
  sign_count    bigint      NOT NULL,
  transports    text[]      NOT NULL DEFAULT '{}',
  name          text        NOT NULL,                             -- PII (low)
  created_at    timestamptz NOT NULL,
  updated_at    timestamptz NOT NULL,
  last_used_at  timestamptz,
  CONSTRAINT webauthn_credentials_credential_id_key UNIQUE (credential_id),
  CONSTRAINT webauthn_credentials_credential_id_check CHECK (octet_length(credential_id) BETWEEN 1 AND 1023),
  CONSTRAINT webauthn_credentials_public_key_check CHECK (octet_length(public_key) BETWEEN 1 AND 4096),
  CONSTRAINT webauthn_credentials_sign_count_check CHECK (sign_count BETWEEN 0 AND 4294967295),
  CONSTRAINT webauthn_credentials_transports_check CHECK (cardinality(transports) <= 10),
  CONSTRAINT webauthn_credentials_name_check CHECK (is_clean_text(name, 1, 40))
);
CREATE INDEX webauthn_credentials_user_id_idx ON webauthn_credentials (user_id);

CREATE TABLE webauthn_challenges (
  id            uuid                       PRIMARY KEY,
  user_id       uuid                       NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  purpose       webauthn_challenge_purpose NOT NULL,
  session_id    uuid                       REFERENCES sessions (id) ON DELETE CASCADE,
  user_token_id uuid                       REFERENCES user_tokens (id) ON DELETE CASCADE,
  challenge     bytea                      NOT NULL,              -- Secret
  created_at    timestamptz                NOT NULL,
  expires_at    timestamptz                NOT NULL,
  CONSTRAINT webauthn_challenges_session_key UNIQUE (session_id),
  CONSTRAINT webauthn_challenges_user_token_key UNIQUE (user_token_id),
  CONSTRAINT webauthn_challenges_challenge_check CHECK (octet_length(challenge) BETWEEN 16 AND 64),
  CONSTRAINT webauthn_challenges_expiry_check CHECK (expires_at = created_at + interval '5 minutes'),
  CONSTRAINT webauthn_challenges_reset_check CHECK (
    (purpose = 'password_reset') = (user_token_id IS NOT NULL AND session_id IS NULL)
  ),
  CONSTRAINT webauthn_challenges_session_check CHECK (purpose = 'password_reset' OR session_id IS NOT NULL)
);
CREATE INDEX webauthn_challenges_expires_at_idx ON webauthn_challenges (expires_at);

-- ---------------------------------------------------------------- recovery codes
CREATE TABLE recovery_codes (
  id         uuid        PRIMARY KEY,
  user_id    uuid        NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  key_id     text        NOT NULL,
  code_hash  bytea       NOT NULL,                                -- Secret: HMAC-SHA-256
  used_at    timestamptz,
  created_at timestamptz NOT NULL,
  updated_at timestamptz NOT NULL,
  CONSTRAINT recovery_codes_user_code_key UNIQUE (user_id, code_hash),
  CONSTRAINT recovery_codes_key_id_check CHECK (key_id ~ '^k[0-9]{1,4}$'),
  CONSTRAINT recovery_codes_code_hash_check CHECK (octet_length(code_hash) = 32)
);
CREATE INDEX recovery_codes_key_id_idx ON recovery_codes (key_id);

-- ---------------------------------------------------------------- audit log
-- app may only INSERT and SELECT (roles.sql); the 90-day purge goes through
-- purge_security_events(), owned by migrator.
CREATE TABLE security_events (
  id             uuid                PRIMARY KEY,
  user_id        uuid                REFERENCES users (id) ON DELETE CASCADE,
  session_id     uuid,                                            -- no FK: sessions are deleted
  budget_id      uuid,                                            -- no FK: budgets are purged
  type           security_event_type NOT NULL,
  device_browser device_browser,                                  -- PII (low)
  device_os      device_os,                                       -- PII (low)
  ip             inet,                                            -- PII (R-6: 90 days)
  created_at     timestamptz         NOT NULL
);
CREATE INDEX security_events_user_created_idx ON security_events (user_id, created_at DESC);
CREATE INDEX security_events_created_at_idx ON security_events (created_at);

-- Deletes only rows older than 90 days by the DATABASE clock. Deliberately takes
-- no argument: a caller-supplied "now" would let the app role erase the audit
-- log (F-26). The only function in the schema that ignores the app clock.
CREATE FUNCTION purge_security_events()
RETURNS bigint
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public, pg_temp
AS $$
DECLARE
  deleted bigint;
BEGIN
  DELETE FROM public.security_events WHERE created_at < now() - interval '90 days';
  GET DIAGNOSTICS deleted = ROW_COUNT;
  RETURN deleted;
END;
$$;
REVOKE ALL ON FUNCTION purge_security_events() FROM PUBLIC;

-- ---------------------------------------------------------------- auth throttles
CREATE TABLE auth_throttles (
  scope        text        NOT NULL,
  key_hash     bytea       NOT NULL,                              -- HMAC, no raw PII
  window_start timestamptz NOT NULL,
  count        integer     NOT NULL,
  created_at   timestamptz NOT NULL,
  updated_at   timestamptz NOT NULL,
  CONSTRAINT auth_throttles_pkey PRIMARY KEY (scope, key_hash, window_start),
  CONSTRAINT auth_throttles_scope_check CHECK (scope ~ '^[a-z][a-z0-9_-]{0,31}:[a-z][a-z0-9_-]{0,31}$'),
  CONSTRAINT auth_throttles_key_hash_check CHECK (octet_length(key_hash) = 32),
  CONSTRAINT auth_throttles_count_check CHECK (count >= 0)
);
CREATE INDEX auth_throttles_window_start_idx ON auth_throttles (window_start);

-- ---------------------------------------------------------------- idempotency keys
CREATE TABLE idempotency_keys (
  user_id       uuid                      NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  key           uuid                      NOT NULL,
  request_hash  bytea                     NOT NULL,               -- Internal, derived from Sensitive
  resource_type idempotency_resource_type NOT NULL,
  resource_id   uuid                      NOT NULL,
  created_at    timestamptz               NOT NULL,
  CONSTRAINT idempotency_keys_pkey PRIMARY KEY (user_id, key),
  CONSTRAINT idempotency_keys_request_hash_check CHECK (octet_length(request_hash) = 32)
);
CREATE INDEX idempotency_keys_created_at_idx ON idempotency_keys (created_at);

-- migrate:down
DROP TABLE idempotency_keys;
DROP TABLE auth_throttles;
DROP FUNCTION purge_security_events();
DROP TABLE security_events;
DROP TABLE recovery_codes;
DROP TABLE webauthn_challenges;
DROP TABLE webauthn_credentials;
DROP TABLE totp_credentials;
DROP TABLE user_tokens;
DROP TABLE signup_invites;
DROP TABLE sessions;
DROP TABLE users;
DROP TYPE security_event_type;
DROP TYPE idempotency_resource_type;
DROP TYPE webauthn_challenge_purpose;
DROP TYPE user_token_purpose;
DROP TYPE device_os;
DROP TYPE device_browser;
DROP TYPE session_status;
DROP TYPE user_status;
DROP FUNCTION is_valid_email(citext);
DROP FUNCTION is_clean_text(text, integer, integer);
-- citext stays installed: other objects may depend on it and dropping an
-- extension needs more than migrator's rights on some hosts.
